package com.scalarwide.main.integer;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Generates fully unrolled CIOS Montgomery kernels for fixed limb counts into
 * {@code build/gen/MontKernels.java}. Same workflow as {@link GenMul}: the generated file is
 * spliced into {@code src/main/java} by hand.
 *
 * <p>Unrolling removes the inner loop, its bounds checks and the dynamic {@code t[j]} indices; the
 * limb products stay identical, so the generated kernels are a pure performance change and are
 * validated by the same differential gate as the generic path.
 */
public final class GenMont {

    // 9 limbs is deliberately absent: the fully unrolled kernel is 22% SLOWER there than the
    // looped path (316 vs 258 ns), because ~150 inlined limb products blow the instruction cache.
    private static final int[] WIDTHS = {4, 6};

    private GenMont() {
    }

    public static void main(String[] args) throws Exception {
        Path dir = Path.of("build", "gen");
        Files.createDirectories(dir);
        Files.writeString(dir.resolve("MontKernels.java"), generate());
        System.out.println("wrote " + dir.resolve("MontKernels.java"));
    }

    private static String generate() {
        List<String> out = new ArrayList<>();
        out.add("package com.scalarwide.main.integer;");
        out.add("");
        out.add("// GENERATED by GenMont -- do not edit by hand.");
        out.add("final class MontKernels {");
        out.add("");
        out.add("    private MontKernels() {");
        out.add("    }");
        out.add("");
        out.add("    /** {@code t[j] += a*b}, returning the carry into {@code t[j+1]}. */");
        out.add("    private static long mulAdd(long[] t, int j, long a, long b, long c) {");
        out.add("        long lo = a * b;");
        out.add("        long hi = Math.unsignedMultiplyHigh(a, b);");
        out.add("        long s = t[j] + lo;");
        out.add("        long c1 = Long.compareUnsigned(s, t[j]) < 0 ? 1L : 0L;");
        out.add("        long s2 = s + c;");
        out.add("        long c2 = Long.compareUnsigned(s2, s) < 0 ? 1L : 0L;");
        out.add("        t[j] = s2;");
        out.add("        return hi + c1 + c2;");
        out.add("    }");
        out.add("");
        out.add("    /** Reduction step: {@code t[j-1] = t[j] + q*m}, returning the carry. */");
        out.add("    private static long redAdd(long[] t, int j, long q, long m, long c) {");
        out.add("        long lo = q * m;");
        out.add("        long hi = Math.unsignedMultiplyHigh(q, m);");
        out.add("        long s = t[j] + lo;");
        out.add("        long c1 = Long.compareUnsigned(s, t[j]) < 0 ? 1L : 0L;");
        out.add("        long s2 = s + c;");
        out.add("        long c2 = Long.compareUnsigned(s2, s) < 0 ? 1L : 0L;");
        out.add("        t[j - 1] = s2;");
        out.add("        return hi + c1 + c2;");
        out.add("    }");
        out.add("");
        out.add("    private static int cmp(long[] t, long[] m, int n) {");
        out.add("        for (int i = n - 1; i >= 0; i--) {");
        out.add("            int c = Long.compareUnsigned(t[i], m[i]);");
        out.add("            if (c != 0) {");
        out.add("                return c;");
        out.add("            }");
        out.add("        }");
        out.add("        return 0;");
        out.add("    }");
        out.add("");
        out.add("    private static void finish(long[] t, long[] m, long[] out, int n) {");
        out.add("        if (t[n] != 0L || cmp(t, m, n) >= 0) {");
        out.add("            long borrow = 0L;");
        out.add("            for (int i = 0; i < n; i++) {");
        out.add("                long d = t[i] - m[i];");
        out.add("                long b = Long.compareUnsigned(t[i], m[i]) < 0 ? 1L : 0L;");
        out.add("                long r = d - borrow;");
        out.add("                if (borrow != 0L && Long.compareUnsigned(r, d) > 0) {");
        out.add("                    b = 1L;");
        out.add("                }");
        out.add("                t[i] = r;");
        out.add("                borrow = b;");
        out.add("            }");
        out.add("        }");
        out.add("        System.arraycopy(t, 0, out, 0, n);");
        out.add("    }");
        for (int n : WIDTHS) {
            out.add("");
            emitKernel(out, n);
        }
        out.add("}");
        return String.join("\n", out) + "\n";
    }

    private static void emitKernel(List<String> out, int n) {
        out.add("    /** Full CIOS for {@code n = " + n + "}; all loops unrolled. */");
        out.add("    static void mulMont" + n
                + "(long[] a, long[] b, long[] m, long n0, long[] t, long[] out) {");
        for (int k = 0; k <= n + 1; k++) {
            out.add("        t[" + k + "] = 0L;");
        }
        for (int i = 0; i < n; i++) {
            out.add("        {");
            out.add("            long bi = b[" + i + "];");
            out.add("            long c = 0L;");
            for (int j = 0; j < n; j++) {
                out.add("            c = mulAdd(t, " + j + ", a[" + j + "], bi, c);");
            }
            out.add("            long s = t[" + n + "] + c;");
            out.add("            t[" + (n + 1) + "] = Long.compareUnsigned(s, t[" + n + "]) < 0 ? 1L : 0L;");
            out.add("            t[" + n + "] = s;");
            out.add("            long q = t[0] * n0;");
            out.add("            long plo = q * m[0];");
            out.add("            long phi = Math.unsignedMultiplyHigh(q, m[0]);");
            out.add("            long s0 = t[0] + plo;");
            out.add("            long carry = phi + (Long.compareUnsigned(s0, t[0]) < 0 ? 1L : 0L);");
            for (int j = 1; j < n; j++) {
                out.add("            carry = redAdd(t, " + j + ", q, m[" + j + "], carry);");
            }
            out.add("            long sum = t[" + n + "] + carry;");
            out.add("            t[" + (n - 1) + "] = sum;");
            out.add("            t[" + n + "] = t[" + (n + 1) + "]"
                    + " + (Long.compareUnsigned(sum, t[" + n + "]) < 0 ? 1L : 0L);");
            out.add("        }");
        }
        out.add("        finish(t, m, out, " + n + ");");
        out.add("    }");
    }
}
